using LootEdit.loot;
using MapEdit;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using MonsterEdit.monsters;
using ProjectTower.audio;
using ProjectTower.config;
using ProjectTower.gamestate;
using ProjectTower.hud;
using ProjectTower.map;
using ProjectTower.particles;
using ProjectTower.player;

namespace ProjectTower.character;

public class CharBuffs
{
	private struct CharBuff(float period)
	{
		public float buffPeriod = period;

		public float totalVal = 0f;

		public float dps = 0f;

		public float buildup = 0f;

		public void AddVal(float val, float buildAdd)
		{
			totalVal += val;
			float num = totalVal / buffPeriod;
			if (num > dps)
			{
				dps = num;
			}
			buildup += buildAdd;
		}
	}

	private CharBuff[] charbuffs;

	public const int CHAR_DEBUFF_SPARK = 0;

	public const int CHAR_DEBUFF_FIRE = 1;

	public const int CHAR_DEBUFF_LIGHTNING = 2;

	public const int CHAR_DEBUFF_NATURAL = 3;

	public const int CHAR_DEBUFF_POISON = 4;

	public const int CHAR_BUFF_FASTER_HEAL = 5;

	public const int CHAR_BUFF_HEAL = 6;

	public const int CHAR_BUFF_PROTECT = 7;

	public const int CHAR_BUFF_FLAME = 8;

	public const int CHAR_BUFF_LIT = 9;

	public const int CHAR_BUFF_FROST = 10;

	public const int CHAR_BUFF_POISON = 11;

	public const int CHAR_BUFF_HOLY = 12;

	public const int CHAR_BUFF_DARK = 13;

	public const int BUFF_MIN = 8;

	public const int BUFF_MAX = 13;

	public const int CHAR_BUFF_LIGHT = 14;

	public const int CHAR_BUFF_FAST_HEAL = 15;

	public const int CHAR_BUFF_UPSIDE_DOWN = 16;

	public const int CHAR_BUFF_ALL = 17;

	public const int CHAR_BUFF_VISION = 18;

	public const int CHAR_BUFF_TORCH = 19;

	public const int CHAR_BUFF_INVINCIBLE = 20;

	public const int CHAR_BUFF_WILL = 21;

	public const int CHAR_DEBUFF_DRUNK = 22;

	public const int CHAR_BUFF_PHYS_DEF = 23;

	public const int CHAR_BUFF_MAG_DEF = 24;

	public const int CHAR_BUFF_MAG_ATK = 25;

	public const int CHAR_DEBUFF_BLOODIED = 26;

	public const int CHAR_BUFF_FOCUS = 27;

	public const int CHAR_BUFF_HEAL_MANA = 28;

	public const int CHAR_BUFF_SLOW_MANA = 29;

	public const int TOTAL_BUFFS = 30;

	private Character c;

	private float frame;

	private float light;

	private float torch;

	private float vision;

	public bool needsFlare;

	public float magBalance;

	private const float DRUNK_MAX = 3f;

	private const float MAG_BALANCE_MAX = 10f;

	public static float ITEM_BUFF_AMT
	{
		get
		{
			if (GameStateManager.mainPlayerIdx <= -1 || !GameModeMgr.IsGameEnhanced())
			{
				return 1f;
			}
			return 0.35f;
		}
	}

	public static float MAGIC_BUFF_AMT
	{
		get
		{
			if (GameStateManager.mainPlayerIdx <= -1 || !GameModeMgr.IsGameEnhanced())
			{
				return 0.6f;
			}
			return 0.225f;
		}
	}

	public static float GREAT_MAGIC_BUFF_AMT
	{
		get
		{
			if (GameStateManager.mainPlayerIdx <= -1 || !GameModeMgr.IsGameEnhanced())
			{
				return 1f;
			}
			return 0.3f;
		}
	}

	public CharBuffs(Character c)
	{
		this.c = c;
		charbuffs = new CharBuff[30];
		charbuffs[0] = new CharBuff(1f);
		charbuffs[1] = new CharBuff(1f);
		charbuffs[2] = new CharBuff(0.25f);
		charbuffs[3] = new CharBuff(3f);
		charbuffs[4] = new CharBuff(20f);
		charbuffs[5] = new CharBuff(1f);
		charbuffs[6] = new CharBuff(10f);
		charbuffs[7] = new CharBuff(10f);
		charbuffs[8] = new CharBuff(30f);
		charbuffs[9] = new CharBuff(30f);
		charbuffs[10] = new CharBuff(30f);
		charbuffs[11] = new CharBuff(30f);
		charbuffs[12] = new CharBuff(30f);
		charbuffs[13] = new CharBuff(30f);
		charbuffs[15] = new CharBuff(5f);
		charbuffs[16] = new CharBuff(30f);
		charbuffs[17] = new CharBuff(10f);
		charbuffs[20] = new CharBuff(1f);
		charbuffs[21] = new CharBuff(1f);
		charbuffs[22] = new CharBuff(20f);
		charbuffs[26] = new CharBuff(20f);
		charbuffs[27] = new CharBuff(30f);
		charbuffs[28] = new CharBuff(5f);
		charbuffs[29] = new CharBuff(30f);
	}

	public void Update()
	{
		if (magBalance < 0f)
		{
			magBalance += Game1.frameTime * 0.5f;
			if (magBalance > 0f)
			{
				magBalance = 0f;
			}
		}
		if (magBalance > 0f)
		{
			magBalance -= Game1.frameTime * 0.5f;
			if (magBalance < 0f)
			{
				magBalance = 0f;
			}
		}
		c.draw.weaponElemType = GetMagicBuff();
		if (c.draw.weaponElemType > 0)
		{
			float magicBuffFrame = GetMagicBuffFrame(c.draw.weaponElemType);
			if (magicBuffFrame < 1f)
			{
				c.draw.weaponElem = magicBuffFrame;
			}
			else if (c.draw.weaponElem < 1f)
			{
				c.draw.weaponElem += Game1.frameTime * 4f;
				if (c.draw.weaponElem > 1f)
				{
					c.draw.weaponElem = 1f;
				}
			}
		}
		else if (c.draw.weaponElem > 0f)
		{
			c.draw.weaponElem -= Game1.frameTime;
			if (c.draw.weaponElem < 0f)
			{
				c.draw.weaponElem = 0f;
			}
		}
		bool flag = charbuffs[16].totalVal > 0f;
		float hp = c.hp;
		if (charbuffs[14].totalVal > 0f)
		{
			if (light < 1f)
			{
				light += Game1.frameTime;
				if (light > 1f)
				{
					light = 1f;
				}
			}
		}
		else if (light > 0f)
		{
			light -= Game1.frameTime;
			if (light < 0f)
			{
				light = 0f;
			}
		}
		if (charbuffs[19].totalVal > 0f)
		{
			if (torch < 1f)
			{
				torch += Game1.frameTime;
				if (torch > 1f)
				{
					torch = 1f;
				}
			}
		}
		else if (torch > 0f)
		{
			torch -= Game1.frameTime;
			if (torch < 0f)
			{
				torch = 0f;
			}
		}
		if (charbuffs[18].totalVal > 0f)
		{
			if (vision < 1f)
			{
				vision += Game1.frameTime;
				if (vision > 1f)
				{
					vision = 1f;
				}
			}
		}
		else if (vision > 0f)
		{
			vision -= Game1.frameTime;
			if (vision < 0f)
			{
				vision = 0f;
			}
		}
		float num = 0.125f;
		frame += Game1.frameTime;
		if (frame > num)
		{
			frame -= num;
			for (int i = 0; i < charbuffs.Length; i++)
			{
				if (!(charbuffs[i].totalVal > 0f))
				{
					continue;
				}
				float num2 = charbuffs[i].dps * num;
				if (num2 > charbuffs[i].totalVal)
				{
					num2 = charbuffs[i].totalVal;
				}
				switch (i)
				{
				case 7:
				case 8:
				case 9:
				case 10:
				case 11:
				case 12:
				case 13:
				case 14:
				case 17:
				case 18:
				case 19:
				case 20:
				case 21:
				case 23:
				case 24:
				case 25:
				case 26:
				case 27:
					num2 = num;
					break;
				}
				charbuffs[i].totalVal -= num2;
				if (charbuffs[i].totalVal <= 0f)
				{
					charbuffs[i].dps = 0f;
					charbuffs[i].buildup = 0f;
				}
				switch (i)
				{
				case 0:
				case 1:
				case 2:
				case 3:
					if (c.hp > 0f)
					{
						MakeHitNumber(i, num2);
					}
					c.update.ReduceHealth(num2);
					if (i == 1)
					{
						c.hpCapDmg += num2 * 0.1f;
					}
					if (i == 2)
					{
						c.spCapDmg += num2 * 0.05f;
						c.stamina -= num2 * 0.2f;
						if (c.playerIdx > -1)
						{
							float sP = c.GetPlayer().stats.GetSP();
							if (sP - c.spCapDmg < c.stats.GetCastMin())
							{
								c.spCapDmg = sP - c.stats.GetCastMin();
							}
						}
					}
					if (c.update.showHP <= 0f)
					{
						c.update.dmgVal = 0f;
					}
					c.update.dmgVal += num2;
					c.update.showHP = 1f;
					c.rects.MakeElemental(i);
					break;
				case 26:
					c.rects.MakeElemental(i);
					break;
				case 22:
					if (charbuffs[i].buildup >= 3f)
					{
						SetBuff(4, num2, 0.1f);
					}
					break;
				case 4:
					if (charbuffs[i].buildup > c.stats.GetPoisonBuildupDefense())
					{
						if (c.hp > 0f)
						{
							MakeHitNumber(i, num2);
						}
						c.update.ReduceHealth(num2);
						if (c.update.showHP <= 0f)
						{
							c.update.dmgVal = 0f;
						}
						c.update.dmgVal += num2;
						c.update.showHP = 1f;
						c.rects.MakeElemental(i);
					}
					break;
				case 17:
				case 25:
				case 27:
					c.rects.MakeElemental(i);
					break;
				case 5:
				case 6:
				case 15:
				{
					for (int k = 0; k < 3; k++)
					{
						ParticleManager.AddAdditiveParticle(37, c.loc + Rand.GetRandomVec2(-40f, 40f, -100f * (flag ? (-1f) : 1f), 0f), c.traj, Rand.GetRandomFloat(0.5f, 1f), Rand.GetRandomFloat(-30f, 30f), 0, c.ID);
					}
					if (c.equipment.active && c.stats.GetRingFlag(23))
					{
						num2 *= 1.25f;
					}
					c.hp += num2;
					if (c.hp > c.stats.GetMaxHP())
					{
						c.hp = c.stats.GetMaxHP();
					}
					break;
				}
				case 21:
				{
					for (int num5 = 0; num5 < 3; num5++)
					{
						int num6 = ParticleManager.AddAdditiveParticle(31, c.loc + Rand.GetRandomVec2(-40f, 40f, -100f * (flag ? (-1f) : 1f), 0f), c.traj, Rand.GetRandomFloat(0.5f, 1f), Rand.GetRandomFloat(-30f, 30f), 0, c.ID);
						if (num6 > -1)
						{
							ParticleManager.particleList[5].particle[num6].aux = 4;
						}
					}
					break;
				}
				case 14:
				{
					for (int n = 0; n < 3; n++)
					{
						ParticleManager.AddAdditiveParticle(31, c.loc + Rand.GetRandomVec2(-40f, 40f, -100f * (flag ? (-1f) : 1f), 0f), c.traj, Rand.GetRandomFloat(0.5f, 1f), Rand.GetRandomFloat(-30f, 30f), 0, c.ID);
					}
					break;
				}
				case 18:
				{
					for (int m = 0; m < 3; m++)
					{
						int num4 = ParticleManager.AddAdditiveParticle(31, c.loc + Rand.GetRandomVec2(-40f, 40f, -100f * (flag ? (-1f) : 1f), 0f), c.traj, Rand.GetRandomFloat(0.5f, 1f), Rand.GetRandomFloat(-30f, 30f), 0, c.ID);
						if (num4 > -1)
						{
							ParticleManager.particleList[5].particle[num4].aux = 4;
						}
					}
					break;
				}
				case 7:
				{
					for (int l = 0; l < 3; l++)
					{
						int num3 = ParticleManager.AddAdditiveParticle(41, c.loc + Rand.GetRandomVec2(-40f, 40f, -100f * (flag ? (-1f) : 1f), 0f), c.traj, Rand.GetRandomFloat(0.5f, 1f), Rand.GetRandomFloat(-30f, 30f), 5, c.ID);
						if (num3 > -1)
						{
							ParticleManager.particleList[5].particle[num3].size *= 0.5f;
							ParticleManager.particleList[5].particle[num3].traj = Rand.GetRandomVec2(0f, 0f, 0f, -100f);
							ParticleManager.particleList[5].particle[num3].traj.X += c.traj.X * 0.25f;
						}
						num3 = ParticleManager.AddBackAdditiveParticle(41, c.loc + Rand.GetRandomVec2(-40f, 40f, -100f * (flag ? (-1f) : 1f), 0f), c.traj, Rand.GetRandomFloat(0.5f, 1f), Rand.GetRandomFloat(-30f, 30f), 5, c.ID);
						if (num3 > -1)
						{
							ParticleManager.particleList[2].particle[num3].size *= 0.5f;
							ParticleManager.particleList[2].particle[num3].traj = Rand.GetRandomVec2(0f, 0f, 0f, -100f);
							ParticleManager.particleList[2].particle[num3].traj.X += c.traj.X * 0.25f;
						}
					}
					break;
				}
				case 28:
				case 29:
				{
					for (int j = 0; j < 3; j++)
					{
						ParticleManager.AddAdditiveParticle(182, c.loc + Rand.GetRandomVec2(-40f, 40f, -100f * (flag ? (-1f) : 1f), 0f), c.traj, Rand.GetRandomFloat(0.5f, 1f), Rand.GetRandomFloat(-30f, 30f), 0, c.ID);
					}
					c.spCapDmg -= num2;
					if (c.spCapDmg < 0f)
					{
						c.spCapDmg = 0f;
					}
					break;
				}
				}
			}
		}
		if (c.hp < hp && c.boss && hp > c.stats.GetMaxHP() * 0.75f && c.hp <= c.stats.GetMaxHP() * 0.75f && PlayerMgr.IsSaltCharacter(c))
		{
			c.rects.MakeRealSaltBomb();
			PlayerMgr.RecoverSalt(c);
		}
	}

	private void MakeHitNumber(int i, float dmg)
	{
		int flags = 0;
		switch (i)
		{
		case 1:
			flags = 2;
			break;
		case 2:
			flags = 3;
			break;
		case 4:
			flags = 5;
			break;
		}
		MonsterDef monsterDef = MonsterCatalog.catalog[c.monsterIdx];
		float num = 0f;
		num = ((!monsterDef.giant) ? monsterDef.boxHeight : c.rects.height);
		ParticleManager.AddNormalParticle(127, c.loc + new Vector2(0f, 0f - num), default, dmg, 0f, flags, c.ID);
	}

	public bool GetAllBuff()
	{
		if (c.equipment.active)
		{
			return false;
		}
		return charbuffs[17].totalVal > 0f;
	}

	public bool GetGoldenBuff()
	{
		if (!c.equipment.active)
		{
			return false;
		}
		return charbuffs[17].totalVal > 0f;
	}

	public bool GetProtect()
	{
		return charbuffs[7].totalVal > 0f;
	}

	public float GetInvincible()
	{
		return charbuffs[20].totalVal;
	}

	public float GetWillBuff()
	{
		return charbuffs[21].totalVal;
	}

	public float GetLight()
	{
		return light;
	}

	public float GetTorch()
	{
		return torch;
	}

	public float GetVision()
	{
		return vision;
	}

	public bool GetDrunk()
	{
		return charbuffs[22].buildup >= 3f;
	}

	public bool GetUpsideDown()
	{
		return charbuffs[16].totalVal > 0f;
	}

	public bool GetMagicBoost()
	{
		return charbuffs[25].totalVal > 0f;
	}

	public bool GetBloodied()
	{
		return charbuffs[26].totalVal > 0f;
	}

	public int GetMagicBuff()
	{
		for (int i = 8; i <= 13; i++)
		{
			if (charbuffs[i].totalVal > 0f)
			{
				return i;
			}
		}
		return 0;
	}

	public float GetBurnt()
	{
		if (charbuffs[1].totalVal > 0f)
		{
			float num = 0.125f;
			float num2 = charbuffs[1].dps * num;
			float num3 = charbuffs[1].totalVal / num2 * 0.1f;
			if (num3 > 0.5f)
			{
				num3 = 0.5f;
			}
			return num3;
		}
		return 0f;
	}

	public float GetMagicBuffFrame(int i)
	{
		return charbuffs[i].totalVal;
	}

	internal void SetBuff(int stat, float val)
	{
		SetBuff(stat, val, 1f);
	}

	internal void EnhanceBuff(int stat, float val = 2f)
	{
		charbuffs[stat].totalVal *= val;
	}

	internal void SetBuff(int stat, float val, float buildAdd)
	{
		if (((uint)(stat - 5) <= 1u || stat == 15) && c.playerIdx > -1 && c.GetPlayer().challenge.category[4].activeChallenge == 0)
		{
			return;
		}
		switch (stat)
		{
		case 8:
		case 9:
		case 10:
		case 11:
		case 12:
		case 13:
			charbuffs[stat].totalVal = 30f;
			if (val > charbuffs[stat].dps)
			{
				charbuffs[stat].dps = val;
			}
			return;
		case 17:
			charbuffs[stat].totalVal = val;
			return;
		case 21:
		case 27:
			charbuffs[stat].totalVal = val;
			return;
		case 7:
			charbuffs[stat].totalVal = 10f;
			return;
		case 23:
			charbuffs[stat].totalVal = val;
			return;
		case 24:
		case 25:
			charbuffs[stat].totalVal = val;
			return;
		case 14:
		case 16:
		case 18:
		case 19:
		case 26:
			charbuffs[stat].totalVal = val;
			return;
		case 20:
			charbuffs[stat].totalVal = 1f;
			return;
		case 2:
			Sound.Play3DSound("zelem", c.loc, 0);
			break;
		case 1:
			if (charbuffs[stat].totalVal <= 0f)
			{
				Sound.Play3DSound("flametrap", c.loc, 0);
				needsFlare = true;
				c.rects.MakeElemental(1);
			}
			break;
		}
		charbuffs[stat].AddVal(val, buildAdd);
	}

	internal void Reset()
	{
		for (int i = 0; i < charbuffs.Length; i++)
		{
			charbuffs[i].totalVal = 0f;
