	internal void AddMagBalance(float val, bool potent)
	{
		if (c.stats.GetRingFlag(34))
		{
			if (!potent)
			{
				return;
			}
			val *= 0.5f;
		}
		if (c.stats.GetRingFlag(33))
		{
			val *= 2f;
		}
		magBalance += val;
		if (magBalance > 10f)
		{
			magBalance = 10f;
			SetBuff(1, c.stats.GetMaxHP() * 0.25f);
		}
		if (magBalance < -10f)
		{
			magBalance = -10f;
			SetBuff(2, c.stats.GetMaxHP() * 0.25f);
		}
	}

